import { Component, OnInit, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { VozackaDozvola, VozackaService } from '../../services/vozacka.service';
import { NgForm } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

declare var bootstrap: any;

@Component({
  selector: 'app-vozacka',
  templateUrl: './vozacka.component.html',
  styleUrls: ['./vozacka.component.css']
})
export class VozackaComponent implements OnInit, AfterViewInit {

  @ViewChild('vozackaModal', { static: false }) vozackaModalRef!: ElementRef;

  vozacke: VozackaDozvola[] = [];
  token: string = '';
  rola: string = '';

  noviZahtev = { grad: '', kategorijeStr: '' };
  modalInstance: any;

  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'error' = 'success';

  constructor(private vozackaService: VozackaService, private authService: AuthService) { }

  ngOnInit(): void {
    this.token = localStorage.getItem('jwtToken') || '';
    this.rola = this.authService.getRoleFromToken();
    this.ucitajVozacke();
  }

  ngAfterViewInit(): void {
    if (this.vozackaModalRef && this.vozackaModalRef.nativeElement) {
      this.modalInstance = new bootstrap.Modal(this.vozackaModalRef.nativeElement);
    }
  }

  openVozackaModal(): void {
    if (this.modalInstance) this.modalInstance.show();
    else console.error('Modal nije inicijalizovan!');
  }

  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    const kategorije = this.noviZahtev.kategorijeStr.split(',').map(k => k.trim());
    const payload = { grad: this.noviZahtev.grad, kategorije };

    this.vozackaService.podnesiZahtev(payload).subscribe({
      next: res => {
        if (this.modalInstance) this.modalInstance.hide();
        form.resetForm();
        this.ucitajVozacke();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Zahtev uspešno podnet!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Došlo je do greške pri podnošenju zahteva.';
        this.showAlert = true;
      }
    });
  }

  ucitajVozacke(): void {
    this.vozackaService.dohvatiSve().subscribe({
      next: (res) => this.vozacke = res,
      error: (err) => console.error(err)
    });
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  get imaAktivanZahtev(): boolean {
    return this.vozacke.some(z => z.status === 'CEKANJE' || z.status === 'DOZVOLJEN');
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

  prihvatiZahtev(id: number) {
    this.vozackaService.odobriZahtev(id).subscribe({
      next: res => {
        this.ucitajVozacke();
        this.alertMessage = res?.message || 'Zahtev je odobren!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertMessage = err.error?.message || 'Došlo je do greške pri odobravanju zahteva.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  odbijZahtev(id: number) {
    this.vozackaService.odbijZahtev(id).subscribe({
      next: res => {
        this.ucitajVozacke();
        this.alertMessage = res?.message || 'Zahtev je odbijen!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertMessage = err.error?.message || 'Došlo je do greške pri odbijanju zahteva.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  produziVozacku() {
    this.vozackaService.produzi().subscribe({
      next: (res: any) => {
        this.ucitajVozacke();
        this.alertType = 'success';
        this.alertMessage = res?.message || 'Vozačka je produžena!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error?.message || 'Dozvola još nije spremna za produženje (više od mesec dana do isteka)';
        this.showAlert = true;
      }
    });
  }


  get mozeProduziti(): boolean {
    return this.vozacke.some(z => z.status === 'DOZVOLJEN');
  }
}
<div class="container mt-5">

  <!-- Alert komponenta -->
  <app-custom-alert
    *ngIf="showAlert"
    [message]="alertMessage"
    [type]="alertType"
    (closed)="closeAlert()">
  </app-custom-alert>

  <!-- Dugme za podnošenje zahteva za vozačku -->
  <div class="d-flex justify-content-center mb-4" *ngIf="!imaAktivanZahtev && !isEmployer">
    <button class="btn btn-primary" (click)="openVozackaModal()">Zahtev za vađenje vozačke dozvole</button>
  </div>

  <!-- Dugme za produženje vozačke (ako postoji DOZVOLJEN zahtev) -->
  <div class="d-flex justify-content-center mb-4" *ngIf="!isEmployer && mozeProduziti">
    <button class="btn btn-warning" (click)="produziVozacku()">Produži vozačku dozvolu</button>
  </div>

  <!-- Tabela vozačkih dozvola -->
  <h3 class="mb-3 text-center">
    {{ isEmployer ? 'Zahtevi za vozačke' : 'Moje vozačke dozvole' }}
  </h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>Datum rođenja</th>
        <th>Datum izdavanja</th>
        <th>Važi do</th>
        <th>Grad</th>
        <th>Broj dozvole</th>
        <th>Kategorije</th>
        <th *ngIf="isEmployer">Status</th>
        <th *ngIf="isEmployer">Akcija</th>
      </tr>
      </thead>
      <tbody>
      <ng-container *ngFor="let vozacka of vozacke; let i = index">
        <tr *ngIf="isEmployer || vozacka.status === 'DOZVOLJEN'">
          <td>{{ i + 1 }}</td>
          <td>{{ vozacka.ime }}</td>
          <td>{{ vozacka.prezime }}</td>
          <td>{{ vozacka.datumRodjenja | date:'dd.MM.yyyy' }}</td>
          <td>{{ vozacka.datumIzdavanja | date:'dd.MM.yyyy' }}</td>
          <td>{{ vozacka.datumVazenja | date:'dd.MM.yyyy' }}</td>
          <td>{{ vozacka.grad }}</td>
          <td>{{ vozacka.brojDozvole }}</td>
          <td>{{ vozacka.kategorije.join(', ') }}</td>
          <td *ngIf="isEmployer" >{{ vozacka.status }}</td>
          <td *ngIf="isEmployer">
            <ng-container *ngIf="vozacka.status !== 'DOZVOLJEN' && vozacka.status !== 'ODBIJEN'">
              <button class="btn btn-success btn-sm me-2" (click)="prihvatiZahtev(vozacka.id)">Prihvati</button>
              <button class="btn btn-danger btn-sm" (click)="odbijZahtev(vozacka.id)">Odbij</button>
            </ng-container>
          </td>
        </tr>
      </ng-container>
      </tbody>
    </table>
  </div>

  <!-- Modal za podnošenje zahteva -->
  <div class="modal fade" id="vozackaModal" #vozackaModal tabindex="-1" aria-labelledby="vozackaModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="vozackaModalLabel">Podnesi zahtev za vozačku dozvolu</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
        </div>
        <div class="modal-body">
          <form #vozackaForm="ngForm" (ngSubmit)="podnesiZahtev(vozackaForm)">
            <div class="mb-3">
              <label for="grad" class="form-label">Grad</label>
              <input type="text" class="form-control" id="grad" name="grad"
                     [(ngModel)]="noviZahtev.grad"
                     required #gradModel="ngModel">
              <div class="text-danger" *ngIf="gradModel.invalid && gradModel.touched">
                Grad je obavezan.
              </div>
            </div>

            <div class="mb-3">
              <label for="kategorije" class="form-label">Kategorije</label>
              <input type="text" class="form-control" id="kategorije" name="kategorije"
                     [(ngModel)]="noviZahtev.kategorijeStr"
                     required #katModel="ngModel"
                     placeholder="Unesite kategorije odvojene zarezom, npr. A,B">
              <div class="text-danger" *ngIf="katModel.invalid && katModel.touched">
                Morate uneti bar jednu kategoriju.
              </div>
            </div>

            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
              <button type="submit" class="btn btn-primary" [disabled]="vozackaForm.invalid">Podnesi zahtev</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>

</div>
